mapper.select:
select d.sku_id as skuId, d.quantity as quantity, d.amount as amount, o.order_no as orderNo, o.create_time as createTime from wms_shipment_order_detail d inner join wms_shipment_order o on d.order_id = o.id where o.merchant_id = #{merchantId} and o.order_status = 1 and d.quantity > 0 and d.amount is not null and d.sku_id in
#{skuId}
order by o.create_time desc, d.id desc
